import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function CustomerDashboard() {
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchUserProfile = async () => {
      const token = localStorage.getItem('token');
      if (!token) {
        setLoading(false);
        return;
      }

      try {
        const res = await axios.get('http://localhost:5000/api/auth/profile', {
          headers: { Authorization: `Bearer ${token}` }
        });
        setProfile(res.data);
      } catch (err) {
        console.error("Failed to retrieve profile bookings database matrix:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchUserProfile();
  }, []);

  if (loading) {
    return (
      <div className="max-w-4xl mx-auto py-16 px-6 text-center text-gray-500 font-semibold tracking-wide">
        Loading your secure hub profile records...
      </div>
    );
  }

  // 🌟 Clean fallbacks to unpack nested profile data safely
  const userData = profile?.user || profile;
  const rawBookings = profile?.bookedCars || profile?.user?.bookedCars || [];

  // 🔍 HIDE AVAILABLE CARS: Only keep cars that are explicitly marked as rented or exist in active booking states
  // If your car schema uses an 'isAvailable' or 'status' flag, we can filter it here directly.
  const activeBookings = rawBookings.filter((booking) => {
    const car = booking?.carId || booking;
    if (!car || !car._id) return false;
    
    // Fallback filter: If the backend model sets availability to true upon return, drop it from dashboard view
    if (car.isAvailable === true || car.status === 'available') {
      return false;
    }
    return true;
  });

  return (
    <div className="max-w-5xl mx-auto py-12 px-6 space-y-8">
      {/* 💳 USER PROFILE CARD OVERVIEW */}
      <div className="bg-white border p-8 rounded-xl shadow-sm">
        <h1 className="text-3xl font-black text-neutral-900 uppercase tracking-tight mb-1">
          Customer Hub
        </h1>
        <p className="text-gray-500 text-sm">
          Welcome back, <span className="font-bold text-neutral-800">{userData?.name || 'Valued Client'}</span>. Track your active fleet rentals below.
        </p>
        <div className="mt-4 flex gap-6 text-xs text-gray-400 font-mono">
          <span>ID Axis: {userData?._id || userData?.id || 'Not Loaded'}</span>
          <span>Email Handle: {userData?.email || 'Not Loaded'}</span>
        </div>
      </div>

      {/* 🚗 BOOKED CARS DIRECTORY SHOWCASE */}
      <div className="bg-white border rounded-xl shadow-sm overflow-hidden">
        <div className="p-6 border-b bg-gray-50/50">
          <h2 className="text-lg font-black text-neutral-900 uppercase tracking-tight">Your Reserved Fleet Vehicles</h2>
        </div>

        <div className="p-6">
          {activeBookings.length === 0 ? (
            <div className="border border-dashed border-gray-300 rounded-lg p-10 text-center bg-gray-50">
              <p className="text-gray-500 font-medium mb-1">You haven't rented any assets yet.</p>
              <p className="text-xs text-gray-400">Head over to our live collection catalog page to reserve your lease today!</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {activeBookings.map((booking) => {
                const car = booking?.carId || booking; 

                return (
                  <div key={booking._id || car._id} className="border border-gray-200 rounded-xl overflow-hidden hover:shadow-md transition duration-200 flex flex-col bg-white">
                    {car.image && (
                      <div className="h-44 bg-neutral-100 overflow-hidden border-b">
                        <img 
                          src={`http://localhost:5000${car.image}`} 
                          alt={`${car.brand} ${car.model}`}
                          className="w-full h-full object-cover"
                        />
                      </div>
                    )}
                    
                    <div className="p-5 flex-1 flex flex-col justify-between space-y-4">
                      <div>
                        <div className="flex justify-between items-start">
                          <h3 className="text-lg font-black text-neutral-900 uppercase tracking-tight">
                            {car.brand} <span className="text-neutral-500 font-medium text-base">{car.model}</span>
                          </h3>
                          <span className="px-2 py-0.5 rounded text-[10px] font-extrabold uppercase tracking-wider bg-yellow-100 text-yellow-800 border border-yellow-200">
                            Active Lease
                          </span>
                        </div>
                        <p className="text-xs text-gray-400 font-medium mt-1">Asset Token ID: {car._id}</p>
                      </div>

                      {/* 🌟 Cleaned Footer Notice: No cost tracking formulas or daily rates showing */}
                      <div className="border-t pt-4 flex justify-between items-center text-xs text-gray-400 font-mono">
                        <span>Status Metric</span>
                        <span className="text-neutral-600 font-bold">Leased Asset Dispatch</span>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {/* ⚠️ FIELD DISPATCH NOTICE */}
      <div className="bg-neutral-900 p-6 rounded-xl text-center text-white shadow-sm">
        <p className="text-sm font-medium opacity-90">
          Need assistance or ready to drop off your vehicle? Coordinate directly with our site check-in marshals.
        </p>
      </div>
    </div>
  );
}
